import sys, threading, http.server, importlib
sys.path.insert(0, '.')
import weather; importlib.reload(weather)
state = {'n': 0, 'fail': 2, 'code': 503}
class H(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        state['n'] += 1
        if state['n'] <= state['fail']:
            self.send_response(state['code']); self.end_headers(); return
        self.send_response(200); self.end_headers(); self.wfile.write(b'{"t": 20}')
    def log_message(self, *a): pass
srv = http.server.HTTPServer(('127.0.0.1', 0), H)
threading.Thread(target=srv.serve_forever, daemon=True).start()
c = weather.WeatherClient(f'http://127.0.0.1:{srv.server_port}', backoff=0.01)
def run(fail, code):
    state.update(n=0, fail=fail, code=code)
    try: r = c.get('x')
    except Exception as e: r = repr(e)
    return r, state['n']
print(run(2, 503))  # succeeds on 3rd
print(run(3, 503))  # exhausts 3 attempts
print(run(1, 500))  # no retry
srv.shutdown()

